/*!
 * Pixel Reveal
 * CDN-ready version
 * Based on original working script
 */

(function () {

  if (typeof gsap === "undefined") {
    console.warn("PixelReveal: GSAP not detected");
    return;
  }

  if (typeof ScrollTrigger !== "undefined") {
    gsap.registerPlugin(ScrollTrigger);
  }

  const DEFAULT_GRID = 12;

  function initPixel(img) {

    const gridSize =
      Math.max(
        1,
        parseInt(img.dataset.grid, 10) || DEFAULT_GRID
      );

    const totalPixels = gridSize * gridSize;

    /* =====================
       WRAPPER
    ====================== */

    const wrapper = document.createElement("div");
    wrapper.className = "image_wrapper";

    img.parentNode.insertBefore(wrapper, img);
    wrapper.appendChild(img);

    /* =====================
       TEXT
    ====================== */

    const content = document.createElement("div");

    content.className = "pixel_content";
    content.textContent = img.dataset.text || "";
    content.style.color =
      img.dataset.textColor || "#fff";

    wrapper.appendChild(content);

    /* =====================
       PIXEL GRID
    ====================== */

    const grid = document.createElement("div");

    grid.className = "pixel_grid";

    grid.style.setProperty(
      "--pixel-color",
      img.dataset.color || "#fff"
    );

    grid.style.gridTemplateColumns =
      `repeat(${gridSize}, 1fr)`;

    grid.style.gridTemplateRows =
      `repeat(${gridSize}, 1fr)`;

    wrapper.appendChild(grid);

    for (let i = 0; i < totalPixels; i++) {
      grid.appendChild(
        document.createElement("div")
      );
    }

    const pixels =
      Array.from(grid.children);

    const duration =
      parseFloat(img.dataset.duration)
      || 0.3;

    const isHover =
      img.hasAttribute("data-hover");

    /* =====================
       TIMELINE
    ====================== */

    const pixelTL =
      gsap.timeline({ paused: true })
        .to(pixels, {
          opacity: 0,
          duration: duration,
          stagger: {
            each: 0.005,
            from: "random"
          },
          ease: "power2.out"
        });

    /* =====================
       HOVER MODE
    ====================== */

    if (isHover) {

      wrapper.addEventListener(
        "mouseenter",
        function () {

          gsap.to(content, {
            opacity: 0,
            duration: 0.2
          });

          pixelTL.restart();

        }
      );

      wrapper.addEventListener(
        "mouseleave",
        function () {

          pixelTL.pause(0);

          gsap.set(pixels, {
            opacity: 1
          });

          gsap.to(content, {
            opacity: 1,
            duration: 0.2
          });

        }
      );

    }

    /* =====================
       SCROLL MODE
    ====================== */

    else {

      if (typeof ScrollTrigger !== "undefined") {

        ScrollTrigger.create({

          trigger: wrapper,
          start: "top 75%",
          once: true,

          onEnter: function () {

            gsap.to(content, {
              opacity: 0,
              duration: 0.3
            });

            pixelTL.play();

          }

        });

      }

    }

  }

  function initAll() {

    const images =
      document.querySelectorAll(
        "img[data-pixel]"
      );

    images.forEach(initPixel);

  }

  if (document.readyState === "loading") {

    document.addEventListener(
      "DOMContentLoaded",
      initAll
    );

  } else {

    initAll();

  }

})();
